import json,re,html
from html.parser import HTMLParser
s=json.load(open('source.json'));a=json.load(open('answer.json'));r=json.load(open('reference-targets.json'))
def plain(v):return html.unescape(re.sub('<["'^>]+>'"','',v))
allowed={'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
class Check(HTMLParser):
 def handle_starttag(self,t,ats):
  assert t in allowed,t
  for k,v in ats:assert k in ['rowspan','colspan'] and v.isdigit(),(k,v)
for i,(x,y) in enumerate(zip(s,a)):
 for k in ['code_id','source_id','number','source_sha256']:assert x[k]==y[k],(i,k)
 assert y['status']=='rewrite_draft'
 Check().feed(y['proposed_xml'])
 si=y['substantive_impact'];assert si['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(si[k])>=40,(i,k)
 for e in si['effects']:
  for k in ['kind','measure_id','description','before','after','unit','affected_population','conditions_and_transition','replacement_or_new_burdens','source_quote','proposed_quote']:assert k in e,(i,k)
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for k,body in [('source_quote',plain(x['source_xml'])),('proposed_quote',plain(y['proposed_xml']))]:
   assert len(e[k])>=12,(i,k)
   assert e[k] in body,(i,k,e[k])
 if y.get('change_type')=='full_repeal':assert plain(y['proposed_xml']).startswith('Le présent article est abrogé') and len(y['repeal_scope'])>=30
 if y.get('change_type')=='normative_reduction':assert all(len(t)>=30 for t in y['removed_provisions'])
 req=r['requirements'][x['code_id']+'|'+x['source_id']]
 assert set(req)=={v['target_key'] for v in y['reference_checks']}
 for v in y['reference_checks']:
  assert v['view_sha256']==r['targets'][v['target_key']]['view_sha256']
  assert len(v['assessment'])>=80
 print(y['number'],y.get('change_type','coordination'),si['classification'],len(y['proposed_xml']),len(si['effects']),len(y['reference_checks']))
assert len(a)==len(s)==12
print('Structure, identifiants, citations exactes, balises et cibles : OK')
PY"

