import json,re,html,hashlib
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text());a=json.loads(Path('answer.json').read_text());r=json.loads(Path('reference-targets.json').read_text())
plain=lambda v:html.unescape(re.sub('<["'^>]+>'"','',v))
class Check(HTMLParser):
 def handle_starttag(self,t,ats):
  assert t in {'p','br','table','thead','tbody','tfoot','tr','th','td','b','strong','i','em','u','sup','sub','ul','ol','li','div','span','blockquote'}
  for k,v in ats:assert k in {'rowspan','colspan'} and v.isdigit()
assert len(a)==len(s)==12
assert len({(v['code_id'],v['source_id']) for v in a})==12
checks=0;effects=0
for x,y in zip(s,a):
 for k in ['code_id','source_id','source_sha256','number']:assert x[k]==y[k]
 assert y['status']=='rewrite_draft' and isinstance(y['proposed_xml'],str)
 Check().feed(y['proposed_xml'])
 si=y['substantive_impact'];assert si['version']==1
 assert si['classification'] in {'material_reduction','coordination_only','retained_necessary','financing_transfer','payment_timing_relief','mixed','reserved','editorial_only'}
 for k in ['assessment','scope_limitations','new_burdens_review']:assert len(si[k])>=40
 for e in si['effects']:
  effects+=1
  assert e['kind'] in {'tax_removed','tax_reduced','obligation_removed','obligation_merged','authorization_removed','regime_merged','deadline_reduced','compliance_cost_reduced','tax_increased','obligation_added','deadline_increased','complexity_added','financing_transfer','payment_deferred','relief_extended','relief_preserved','coordination'}
  assert e['unit'] in {'percent','euro','legal_duty','regime','calendar_days','working_days','financing','other'}
  assert re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)*',e['measure_id']) and 6<=len(e['measure_id'])<=96
  for k,body in [('source_quote',plain(x['source_xml'])),('proposed_quote',plain(y['proposed_xml']))]:assert len(e[k])>=12 and e[k] in body,(x['number'],k)
 if y.get('change_type')=='full_repeal':
  assert plain(y['proposed_xml']).startswith('Le présent article est abrogé')
  assert y['repeal_policy_id']=='editorial_direction_2026_10_19' and len(y['repeal_scope'])>=30
 if y.get('change_type')=='normative_reduction':
  assert y['reform_policy_id']=='editorial_direction_2026_10_19'
  assert y['removed_provisions'] and all(len(v)>=30 for v in y['removed_provisions'])
 key=x['code_id']+'|'+x['source_id']
 assert sorted(r['requirements'][key])==sorted(v['target_key'] for v in y['reference_checks'])
 for v in y['reference_checks']:
  checks+=1;assert v['view_sha256']==r['targets'][v['target_key']]['view_sha256'] and len(v['assessment'])>=80
 if x.get('benefit_check_required'):assert len(y['benefit_review'])>=100
 assert not any(p in y['proposed_xml'] for p in ['texte inchangé','[...','…','<script','<a '])
print('Contrôles formels terminés : 12 articles,',checks,'analyses de cibles,',effects,'effets documentés (mesures dédupliquées par identifiant).')
for i in [2,3,10]:
 print('\\nRELECTURE FINALE '+a[i]['number']+'\\n'+a[i]['proposed_xml'])
print('\\nanswer.json',Path('answer.json').stat().st_size,'octets ; SHA256',hashlib.sha256(Path('answer.json').read_bytes()).hexdigest())
PY"

